const express = require("express");
const router = express.Router();
const supabase = require("../config/supabase");

// GET /api/appointments
// Supports filtering by vetId
router.get("/", async function (req, res) {
  try {
    const vetId = req.query.vetId;
    const ownerId = req.query.ownerId;

    let query = supabase.from('appointments').select('*').order('createdAt', { ascending: false });

    if (vetId) query = query.eq('vetId', vetId);
    if (ownerId) query = query.eq('ownerId', ownerId);

    const { data: dbAppointments, error } = await query;
    if (error) throw error;

    return res.json({
      success: true,
      count: dbAppointments.length,
      appointments: dbAppointments
    });
  } catch(err) {
    return res.status(500).json({ success: false, message: err.message });
  }
});

// POST /api/appointments
router.post("/", async function (req, res) {
  try {
    const body = req.body;

    const { data: newAppt, error } = await supabase
      .from('appointments')
      .insert([body])
      .select()
      .single();

    if (error) throw error;

    return res.status(201).json({ success: true, appointment: newAppt });
  } catch (err) {
    return res.status(500).json({ success: false, message: err.message });
  }
});

// PUT /api/appointments/:id/status
router.put("/:id/status", async function (req, res) {
  try {
    const { id } = req.params;
    const { status, meetLink } = req.body;

    const updateData = { status };
    if (meetLink !== undefined) {
      updateData.meetLink = meetLink;
    }

    const { data: updatedAppointment, error } = await supabase
      .from('appointments')
      .update(updateData)
      .eq('_id', id)
      .select()
      .maybeSingle();

    if (error) throw error;

    if (!updatedAppointment) {
       return res.status(404).json({ success: false, message: "Appointment not found." });
    }

    // Also update the related Consultation if it exists
    await supabase
      .from('consultations')
      .update(updateData)
      .eq('appointmentId', id);

    return res.json({ success: true, appointment: updatedAppointment });
  } catch (err) {
    return res.status(500).json({ success: false, message: err.message });
  }
});

module.exports = router;

