const express = require("express");
const router = express.Router();
const supabase = require("../config/supabase");

// GET /api/consultations
// Supports filtering by vetId or ownerId
router.get("/", async function (req, res) {
  try {
    const vetId = req.query.vetId;
    const ownerId = req.query.ownerId;

    let query = supabase.from('consultations').select('*').order('createdAt', { ascending: false });

    if (vetId) query = query.eq('vetId', vetId);
    if (ownerId) query = query.eq('ownerId', ownerId);

    const { data: dbConsultations, error } = await query;
    if (error) throw error;

    return res.json({
      success: true,
      count: dbConsultations.length,
      data: dbConsultations
    });
  } catch(err) {
    return res.status(500).json({ success: false, message: err.message });
  }
});

// GET /api/consultations/metrics
router.get("/metrics", async function (req, res) {
  try {
    const vetId = req.query.vetId;
    if (!vetId) {
      return res.status(400).json({ success: false, message: "vetId is required" });
    }

    const today = new Date();
    const todayStr = today.toISOString().split("T")[0]; // YYYY-MM-DD

    const { data: allConsults, error } = await supabase
      .from('consultations')
      .select('*')
      .eq('vetId', vetId);

    if (error) throw error;

    const metrics = {
      totalConsultations: allConsults.length,
      completedConsultations: allConsults.filter(c => c.status === 'completed').length,
      upcomingConsultations: allConsults.filter(c => c.status === 'upcoming').length,
      todayConsultations: allConsults.filter(c => c.date === todayStr).length,
      totalEarnings: allConsults.filter(c => c.status === 'completed').reduce((sum, c) => sum + (Number(c.fee) || 499), 0),
      rating: 4.8 // Default or mocked for now
    };

    return res.json({ success: true, data: metrics });
  } catch(err) {
    return res.status(500).json({ success: false, message: err.message });
  }
});

// GET /api/consultations/:id
router.get("/:id", async function (req, res) {
  try {
    const { id } = req.params;

    const { data: consultation, error } = await supabase
      .from('consultations')
      .select('*')
      .or(`_id.eq.${id},appointmentId.eq.${id}`)
      .maybeSingle();

    if (error) throw error;

    if (!consultation) {
      return res.status(404).json({ success: false, message: "Consultation not found." });
    }

    return res.json({ success: true, data: consultation });
  } catch(err) {
    return res.status(500).json({ success: false, message: err.message });
  }
});

// POST /api/consultations
router.post("/", async function (req, res) {
  try {
    const body = req.body;

    const { data: newConsultation, error } = await supabase
      .from('consultations')
      .insert([body])
      .select()
      .single();

    if (error) throw error;

    return res.status(201).json({ success: true, data: newConsultation });
  } catch (err) {
    return res.status(500).json({ success: false, message: err.message });
  }
});

// PUT /api/consultations/:id/notes
router.put("/:id/notes", async function (req, res) {
  try {
    const { id } = req.params;
    const { clinicalNotes } = req.body;

    const { data: updatedConsultation, error } = await supabase
      .from('consultations')
      .update({ clinicalNotes })
      .eq('_id', id)
      .select()
      .maybeSingle();

    if (error) throw error;

    if (!updatedConsultation) {
       return res.status(404).json({ success: false, message: "Consultation not found." });
    }

    return res.json({ success: true, data: updatedConsultation });
  } catch (err) {
    return res.status(500).json({ success: false, message: err.message });
  }
});

// PUT /api/consultations/:id/status
router.put("/:id/status", async function (req, res) {
  try {
    const { id } = req.params;
    const { status } = req.body;

    const { data: updatedConsultation, error } = await supabase
      .from('consultations')
      .update({ status })
      .eq('_id', id)
      .select()
      .maybeSingle();

    if (error) throw error;

    if (!updatedConsultation) {
       return res.status(404).json({ success: false, message: "Consultation not found." });
    }

    return res.json({ success: true, data: updatedConsultation });
  } catch (err) {
    return res.status(500).json({ success: false, message: err.message });
  }
});

// DELETE /api/consultations/:id
router.delete("/:id", async function (req, res) {
  try {
    const { id } = req.params;

    const { data: deletedConsultation, error } = await supabase
      .from('consultations')
      .delete()
      .eq('_id', id)
      .select()
      .maybeSingle();

    if (error) throw error;

    if (!deletedConsultation) {
       return res.status(404).json({ success: false, message: "Consultation not found." });
    }

    return res.json({ success: true, message: "Consultation deleted." });
  } catch (err) {
    return res.status(500).json({ success: false, message: err.message });
  }
});

module.exports = router;

