const express = require("express");
const router = express.Router();
const supabase = require("../config/supabase");

// GET /api/prescriptions
router.get("/", async function (req, res) {
  try {
    const vetId = req.query.vetId;
    const ownerId = req.query.ownerId; // Not easily available in prescriptions table unless added

    let query = supabase.from('prescriptions').select('*').order('createdAt', { ascending: false });

    if (vetId) {
      query = query.eq('vetId', vetId);
    }

    const { data: dbPrescriptions, error } = await query;
    if (error) throw error;

    let filtered = dbPrescriptions;
    if (ownerId) {
       // Since ownerId is not directly in prescriptions, we would normally join appointments.
       // Without a join, we can fetch appointments for the owner and filter.
       const { data: appts } = await supabase.from('appointments').select('_id').eq('ownerId', ownerId);
       const apptIds = (appts || []).map(a => a._id);

       filtered = filtered.filter(p => apptIds.includes(p.appointmentId));
    }
    return res.json({ success: true, data: filtered });
  } catch (err) {
    return res.status(500).json({ success: false, message: err.message });
  }
});

// GET /api/prescriptions/:id
router.get("/:id", async function (req, res) {
  try {
    const { id } = req.params;

    const { data: prescription, error } = await supabase
      .from('prescriptions')
      .select('*')
      .eq('_id', id)
      .maybeSingle();

    if (error) throw error;

    if (!prescription) {
      return res.status(404).json({ success: false, message: "Prescription not found." });
    }
    return res.json({ success: true, data: prescription });
  } catch(err) {
    return res.status(500).json({ success: false, message: err.message });
  }
});

// POST /api/prescriptions
router.post("/", async function (req, res) {
  try {
    const body = req.body;

    const { data: newPrescription, error } = await supabase
      .from('prescriptions')
      .insert([body])
      .select()
      .single();

    if (error) throw error;

    return res.status(201).json({
      success: true,
      message: "Prescription issued successfully",
      prescription: newPrescription
    });
  } catch (err) {
    return res.status(500).json({ success: false, message: err.message });
  }
});

module.exports = router;

